const COLLECTION = '@nx/angular';
const OLD_GENERATOR = 'ngrx';
const ROOT_STORE_GENERATOR = 'ngrx-root-store';
const FEATURE_STORE_GENERATOR = 'ngrx-feature-store';

const ROOT_STORE_OPTIONS = ['facade', 'minimal', 'directory'] as const;
const FEATURE_STORE_OPTIONS = ['facade', 'barrels', 'directory'] as const;

type Generators = Record<string, any>;

export default async function migrateNgrxGeneratorDefaults(
  tree: Tree
): Promise<void> {
  let changed = false;

  const nxJson = readNxJson(tree);
  if (nxJson?.generators && migrateGenerators(nxJson.generators)) {
    updateNxJson(tree, nxJson);
    changed = true;
  }

  const projects = getProjects(tree);
  for (const [projectName, projectConfig] of projects) {
    if (projectConfig.generators && migrateGenerators(projectConfig.generators)) {
      updateProjectConfiguration(tree, projectName, projectConfig);
      changed = true;
    }
  }

  if (changed) {
    await formatFiles(tree);
  }
}

/**
 * Redistributes any old `@nx/angular:ngrx` generator defaults (flat or nested)
 * into the new `ngrx-root-store` and `ngrx-feature-store` generators.
 * Returns whether any change was made.
 */
function migrateGenerators(generators: Generators): boolean {
  const flatKey = `${COLLECTION}:${OLD_GENERATOR}`;
  const flatOld = generators[flatKey];
  const nestedOld = generators[COLLECTION]?.[OLD_GENERATOR];

  if (!flatOld && !nestedOld) {
    return false;
  }

  // When both formats coexist, flat takes precedence over nested and the
  // output is written in flat format.
  const oldOptions: Generators =
    flatOld && nestedOld
      ? { ...nestedOld, ...flatOld }
      : { ...(flatOld ?? nestedOld) };
  const preferFlat = !!flatOld;

  const rootOptions = pick(oldOptions, ROOT_STORE_OPTIONS);
  const featureOptions = pick(oldOptions, FEATURE_STORE_OPTIONS);

  // Rename the old `module` option to `parent` on the feature store, with
  // `module` taking precedence over any pre-existing `parent`.
  if ('module' in oldOptions) {
    featureOptions.parent = oldOptions.module;
  } else if ('parent' in oldOptions) {
    featureOptions.parent = oldOptions.parent;
  }
  // The obsolete `root` toggle is dropped entirely.

  // Remove the old defaults.
  delete generators[flatKey];
  if (nestedOld) {
    delete generators[COLLECTION][OLD_GENERATOR];
  }

  writeGeneratorDefaults(generators, ROOT_STORE_GENERATOR, rootOptions, preferFlat);
  writeGeneratorDefaults(
    generators,
    FEATURE_STORE_GENERATOR,
    featureOptions,
    preferFlat
  );

  // Clean up the nested collection bucket if it was emptied out.
  if (
    generators[COLLECTION] &&
    Object.keys(generators[COLLECTION]).length === 0
  ) {
    delete generators[COLLECTION];
  }

  return true;
}

function writeGeneratorDefaults(
  generators: Generators,
  generator: string,
  migratedOptions: Generators,
  preferFlat: boolean
): void {
  const flatKey = `${COLLECTION}:${generator}`;
  const existingFlat = generators[flatKey];
  const existingNested = generators[COLLECTION]?.[generator];

  // Merge migrated options into any existing defaults, letting the user-set
  // values on the new keys take priority. Keep the format the user already
  // used for the new key.
  if (existingNested !== undefined) {
    generators[COLLECTION][generator] = {
      ...migratedOptions,
      ...existingNested,
    };
    return;
  }
  if (existingFlat !== undefined) {
    generators[flatKey] = { ...migratedOptions, ...existingFlat };
    return;
  }

  // Nothing to write and no existing key to merge into: do not create empty
  // defaults.
  if (Object.keys(migratedOptions).length === 0) {
    return;
  }

  if (preferFlat) {
    generators[flatKey] = migratedOptions;
  } else {
    generators[COLLECTION] ??= {};
    generators[COLLECTION][generator] = migratedOptions;
  }
}

function pick(source: Generators, keys: readonly string[]): Generators {
  const result: Generators = {};
  for (const key of keys) {
    if (key in source) {
      result[key] = source[key];
    }
  }
  return result;
}
