+const COLLECTION='@nx/angular',OLD='ngrx',ROOT='ngrx-root-store',FEAT='ngrx-feature-store';
+const RO=['facade','minimal','directory'],FO=['facade','barrels','directory'];
+function pick(s,k){const r={};for(const x of k)if(x in s)r[x]=s[x];return r;}
+function write(g,gen,opts,flat){const fk=`${COLLECTION}:${gen}`;const ef=g[fk];const en=g[COLLECTION]?.[gen];
+ if(en!==undefined){g[COLLECTION][gen]={...opts,...en};return;} if(ef!==undefined){g[fk]={...opts,...ef};return;}
+ if(Object.keys(opts).length===0)return; if(flat)g[fk]=opts; else {g[COLLECTION]??={};g[COLLECTION][gen]=opts;}}
+function mig(g){const fk=`${COLLECTION}:${OLD}`;const fo=g[fk];const no=g[COLLECTION]?.[OLD];
+ if(!fo&&!no)return false;
+ const old=fo&&no?{...no,...fo}:{...(fo??no)};const pf=!!fo;
+ const ro=pick(old,RO),feo=pick(old,FO);
+ if('module'in old)feo.parent=old.module;else if('parent'in old)feo.parent=old.parent;
+ delete g[fk];if(no)delete g[COLLECTION][OLD];
+ write(g,ROOT,ro,pf);write(g,FEAT,feo,pf);
+ if(g[COLLECTION]&&Object.keys(g[COLLECTION]).length===0)delete g[COLLECTION];
+ return true;}
